// The rung the whole domain is built for. Level falls from the customer's draw
// and from boil-off together, and stops at empty so Euler cannot drive it
// negative. Pressure rises as boil-off gas fills whatever ullage is left, so a
// nearly full tank pressurises fastest, and falls as liquid is drawn off. Empty
// stops the customer's line and full opens the relief valve, so the safe region
// is an interval and "hold more stock" is not a safe default.
export default Dynamics((tokens, parameters) => {
  return tokens.map((unit) => ({
    level: unit.level > 0 ? -(unit.draw + parameters.boiloff_rate) : 0, pressure: Math.max(parameters.pressure_gain * parameters.boiloff_rate / Math.max(unit.capacity - unit.level, 1) - parameters.pressure_vented_by_draw * unit.draw, unit.pressure > 1 ? -1 : 0), capacity: 0, draw: 0, drawn: unit.level > 0 ? unit.draw : 0, boiled: unit.level > 0 ? parameters.boiloff_rate : 0, spilled: 0
  }));
});

export default Dynamics((tokens) => {
