const drawn2 = state.places.SlowNitrogenTank.tokens.reduce((sum, tank) => sum + tank.drawn, 0);
const drawn3 = state.places.CriticalOxygenTank.tokens.reduce((sum, tank) => sum + tank.drawn, 0);
return drawn1 + drawn2 + drawn3;

